DROP PROCEDURE IF EXISTS USP_GET_OFFICE_BARCODE_STOCK;
DELIMITER $$
CREATE PROCEDURE USP_GET_OFFICE_BARCODE_STOCK(IN pProd_Id INT,
    IN pAsOnDate DATE,
    IN pExclude_Id INT,
    IN pExclude_Stock_Type TINYINT)
BEGIN

    SELECT
        b.Barcode,
        b.MRP,
        (b.Avil_Qnty + CASE WHEN c.Barcode_Count = 1 THEN IFNULL(u.Unbar_Qnty, 0) ELSE 0 END) AS Avil_Qnty,
        b.Purchase_Id,
        b.Last_Id
    FROM (
        SELECT
            s.Barcode AS Barcode,
            CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(
            CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND ag.TrnsStock_Id IS NULL THEN s.Quantity
                WHEN pExclude_Stock_Type = 7 AND s.Stock_Type = 7
                     AND pExclude_Id > 0 AND IFNULL(s.Type_Id, 0) = pExclude_Id THEN 0
                WHEN pExclude_Stock_Type = 9 AND s.Stock_Type = 9
                     AND pExclude_Id > 0 AND IFNULL(s.Type_Id, 0) = pExclude_Id THEN 0
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Avil_Qnty,
            MAX(CASE WHEN s.Stock_Type = 2 THEN s.Stock_Id END) AS Purchase_Id,
            MAX(s.Stock_Id) AS Last_Id
        FROM trns_stockinout s
        
            LEFT JOIN (
                SELECT DISTINCT TrnsStock_Id
                FROM trans_agent_stock
                WHERE TrnsStock_Id IS NOT NULL
            ) ag ON ag.TrnsStock_Id = s.Stock_Id
        WHERE s.Prod_Id = pProd_Id
          AND s.InOut_Date <= pAsOnDate
          AND IFNULL(s.Barcode, 0) <> 0
        GROUP BY s.Barcode
    ) b
    LEFT JOIN (
        SELECT MRP, COUNT(*) AS Barcode_Count
        FROM (
            SELECT
                s.Barcode,
                CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP
            FROM trns_stockinout s
            WHERE s.Prod_Id = pProd_Id
              AND s.InOut_Date <= pAsOnDate
              AND IFNULL(s.Barcode, 0) <> 0
            GROUP BY s.Barcode
        ) m
        GROUP BY MRP
    ) c ON c.MRP = b.MRP
    LEFT JOIN (
        SELECT
            CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(
            CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND ag.TrnsStock_Id IS NULL THEN s.Quantity
                WHEN pExclude_Stock_Type = 7 AND s.Stock_Type = 7
                     AND pExclude_Id > 0 AND IFNULL(s.Type_Id, 0) = pExclude_Id THEN 0
                WHEN pExclude_Stock_Type = 9 AND s.Stock_Type = 9
                     AND pExclude_Id > 0 AND IFNULL(s.Type_Id, 0) = pExclude_Id THEN 0
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Unbar_Qnty
        FROM trns_stockinout s
        
            LEFT JOIN (
                SELECT DISTINCT TrnsStock_Id
                FROM trans_agent_stock
                WHERE TrnsStock_Id IS NOT NULL
            ) ag ON ag.TrnsStock_Id = s.Stock_Id
        WHERE s.Prod_Id = pProd_Id
          AND s.InOut_Date <= pAsOnDate
          AND IFNULL(s.Barcode, 0) = 0
        GROUP BY CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2))
    ) u ON u.MRP = b.MRP
    ORDER BY b.Purchase_Id DESC, b.Last_Id DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_OFFICE_UNBARCODED_PURCHASE_RETURNS;
DELIMITER $$
CREATE PROCEDURE USP_GET_OFFICE_UNBARCODED_PURCHASE_RETURNS(IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
        IFNULL(SUM(s.Quantity), 0) AS Qty
    FROM trns_stockinout s
    WHERE s.Prod_Id = pProd_Id
      AND s.InOut_Date <= pAsOnDate
      AND s.Stock_Type = 7
      AND IFNULL(s.Barcode, 0) = 0
    GROUP BY CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2));

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_OFFICE_BARCODE_STOCK_SIMPLE;
DELIMITER $$
CREATE PROCEDURE USP_GET_OFFICE_BARCODE_STOCK_SIMPLE(IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        s.Barcode AS Barcode,
        CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
        IFNULL(SUM(
            CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND ag.TrnsStock_Id IS NULL THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END
        ), 0) AS Avil_Qnty
    FROM trns_stockinout s
    
            LEFT JOIN (
                SELECT DISTINCT TrnsStock_Id
                FROM trans_agent_stock
                WHERE TrnsStock_Id IS NOT NULL
            ) ag ON ag.TrnsStock_Id = s.Stock_Id
    WHERE s.Prod_Id = pProd_Id
      AND s.InOut_Date <= pAsOnDate
      AND IFNULL(s.Barcode, 0) <> 0
    GROUP BY s.Barcode
    HAVING Avil_Qnty > 0
    ORDER BY MAX(CASE WHEN s.Stock_Type = 2 THEN s.Stock_Id END) DESC, MAX(s.Stock_Id) DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_PRODUCT_BARCODES;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_PRODUCT_BARCODES(IN pAgent_Id INT,
    IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        x.Barcode AS Barcode,
        CAST(MAX(x.MRP) AS DECIMAL(10,2)) AS MRP,
        SUM(x.Qty) AS Avil_Qnty
    FROM (
        SELECT
            COALESCE(NULLIF(s.Barcode, 0), (
                SELECT p.Barcode
                  FROM trns_stockinout p
                 WHERE p.Prod_Id = s.Prod_Id
                   AND p.Stock_Type IN (1, 2)
                   AND IFNULL(p.Barcode, 0) <> 0
                   AND (IFNULL(s.MRP, 0) = 0 OR ROUND(p.MRP, 2) = ROUND(s.MRP, 2))
                 ORDER BY (p.Stock_Type = 2) DESC, p.Stock_Id DESC
                 LIMIT 1
            )) AS Barcode,
            IFNULL(NULLIF(s.MRP, 0), (
                SELECT p.MRP
                  FROM trns_stockinout p
                 WHERE p.Prod_Id = s.Prod_Id
                   AND p.Stock_Type IN (1, 2)
                   AND IFNULL(p.Barcode, 0) <> 0
                   AND (IFNULL(s.MRP, 0) = 0 OR ROUND(p.MRP, 2) = ROUND(s.MRP, 2))
                 ORDER BY (p.Stock_Type = 2) DESC, p.Stock_Id DESC
                 LIMIT 1
            )) AS MRP,
            CASE
                WHEN s.Stock_Type IN (4, 8) THEN s.Quantity
                WHEN s.Stock_Type IN (5, 6) THEN -s.Quantity
                ELSE 0
            END AS Qty
        FROM trns_stockinout s
        INNER JOIN trans_agent_stock a ON a.TrnsStock_Id = s.Stock_Id
        WHERE a.Agent_Id = pAgent_Id
          AND a.Prod_Id = pProd_Id
          AND a.Trans_Date <= pAsOnDate
          AND s.Stock_Type IN (4, 5, 6, 8)
    ) x
    WHERE IFNULL(x.Barcode, 0) <> 0
    GROUP BY x.Barcode
    HAVING Avil_Qnty > 0
    ORDER BY MAX(x.MRP) DESC, x.Barcode DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_RETURN_ITEMS;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_RETURN_ITEMS(IN pAgent_Id INT,
    IN pAsOnDate DATE,
    IN pCat_Id INT,
    IN pSubCat_Id INT,
    IN pCode VARCHAR(100),
    IN pCodeLike VARCHAR(120))
BEGIN

    SELECT
        p.Prod_Id,
        p.Prod_Code,
        p.Prod_ShortNm,
        p.Unit_Id,
        IFNULL(UDF_GET_UNIT_NAME(p.Unit_Id), '') AS Unit_Name,
        CAST(IFNULL(MAX(CASE WHEN s.Stock_Type = 4 THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
        IFNULL(SUM(CASE s.Stock_Type
            WHEN 4 THEN s.Quantity
            WHEN 6 THEN -s.Quantity
            WHEN 5 THEN -s.Quantity
            WHEN 8 THEN s.Quantity
            ELSE 0
        END), 0) AS Avil_Qnty
    FROM trns_stockinout s
    INNER JOIN trans_agent_stock a ON a.TrnsStock_Id = s.Stock_Id
    INNER JOIN mst_product p ON p.Prod_Id = s.Prod_Id
    WHERE a.Agent_Id = pAgent_Id
      AND s.Stock_Type IN (4, 5, 6, 8)
      AND s.InOut_Date <= pAsOnDate
      AND (pCat_Id = 0 OR p.Cate_Id = pCat_Id)
      AND (pSubCat_Id = 0 OR p.SubCate_Id = pSubCat_Id)
      AND (
            pCode = ''
            OR p.Prod_Code LIKE pCodeLike
            OR p.Prod_ShortNm LIKE pCodeLike
      )
    GROUP BY p.Prod_Id, p.Prod_Code, p.Prod_ShortNm, p.Unit_Id
    HAVING Avil_Qnty > 0
    ORDER BY p.Prod_ShortNm, p.Prod_Code;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_RETURN_BARCODES;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_RETURN_BARCODES(IN pAgent_Id INT,
    IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        s.Barcode,
        CAST(IFNULL(MAX(CASE WHEN s.Stock_Type = 4 THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
        IFNULL(SUM(CASE s.Stock_Type
            WHEN 4 THEN s.Quantity
            WHEN 6 THEN -s.Quantity
            WHEN 5 THEN -s.Quantity
            WHEN 8 THEN s.Quantity
            ELSE 0
        END), 0) AS Avil_Qnty
    FROM trns_stockinout s
    INNER JOIN trans_agent_stock a ON a.TrnsStock_Id = s.Stock_Id
    WHERE a.Agent_Id = pAgent_Id
      AND s.Prod_Id = pProd_Id
      AND s.Stock_Type IN (4, 5, 6, 8)
      AND s.InOut_Date <= pAsOnDate
      AND IFNULL(s.Barcode, 0) <> 0
    GROUP BY s.Barcode
    HAVING Avil_Qnty > 0
    ORDER BY MRP DESC, MAX(s.Stock_Id) DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_ISSUE_BARCODE;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_ISSUE_BARCODE(IN pAgent_Id INT,
    IN pProd_Id INT)
BEGIN

    SELECT s.Barcode
    FROM trns_stockinout s
    INNER JOIN trans_agent_stock a ON a.TrnsStock_Id = s.Stock_Id
    WHERE a.Agent_Id = pAgent_Id
      AND s.Prod_Id = pProd_Id
      AND s.Stock_Type = 4
      AND IFNULL(s.Barcode, 0) <> 0
    ORDER BY s.Stock_Id DESC
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_SOLD_BARCODES_FOR_RETURN;
DELIMITER $$
CREATE PROCEDURE USP_GET_SOLD_BARCODES_FOR_RETURN(IN pExclude_Return_Id INT,
    IN pAsOnDate DATE,
    IN pProd_Id INT,
    IN pBarcode VARCHAR(30),
    IN pSale_Id INT)
BEGIN

    SELECT
        s.Barcode AS Barcode,
        MAX(s.Prod_Id) AS Prod_Id,
        CAST(IFNULL(MAX(CASE WHEN s.Stock_Type = 3 THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
        CAST(IFNULL(MAX(CASE WHEN s.Stock_Type = 3 THEN s.Rate END), 0) AS DECIMAL(10,2)) AS Rate,
        IFNULL(SUM(CASE WHEN s.Stock_Type = 3 THEN s.Quantity ELSE 0 END), 0) AS Sold_Qty,
        IFNULL(SUM(CASE
            WHEN s.Stock_Type = 8
             AND ag.TrnsStock_Id IS NULL
             AND (pExclude_Return_Id = 0 OR IFNULL(s.Type_Id, 0) <> pExclude_Return_Id)
            THEN s.Quantity ELSE 0 END), 0) AS Returned_Qty
    FROM trns_stockinout s
    
            LEFT JOIN (
                SELECT DISTINCT TrnsStock_Id
                FROM trans_agent_stock
                WHERE TrnsStock_Id IS NOT NULL
            ) ag ON ag.TrnsStock_Id = s.Stock_Id
    WHERE s.InOut_Date <= pAsOnDate
      AND IFNULL(s.Barcode, 0) <> 0
      AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
      AND (pBarcode = '' OR s.Barcode = pBarcode)
      AND (
            s.Stock_Type = 8
            OR (s.Stock_Type = 3 AND (pSale_Id = 0 OR s.Type_Id = pSale_Id))
      )
    GROUP BY s.Barcode
    HAVING Sold_Qty > 0
    ORDER BY s.Barcode;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_SALE_LINE_ITEMS;
DELIMITER $$
CREATE PROCEDURE USP_GET_SALE_LINE_ITEMS(IN pTrading_Id INT)
BEGIN

    SELECT
        p.Prod_Id,
        i.Cate_Id AS Cat_Id,
        i.Prod_ShortNm AS Prod_Name,
        i.Prod_Code,
        p.Gst_Code AS hsn_code,
        p.Item_Qty AS qnty,
        p.Item_Rate,
        p.Unit_Id,
        UDF_GET_UNIT_NAME(p.Unit_Id) AS Unit_Name,
        p.Item_Total,
        p.MRP,
        p.Disc_Prcnt,
        p.Disc_Amt,
        p.Taxable_Amt,
        p.SGST_Prcnt,
        p.CGST_Prcnt,
        p.SGST_Amt,
        p.CGST_Amt,
        p.Net_Amt,
        s.Pack_Date,
        s.Barcode
    FROM (
        SELECT tp.*,
               ROW_NUMBER() OVER (
                   PARTITION BY tp.Prod_Id, tp.Item_Qty, ROUND(tp.Item_Rate, 2), ROUND(IFNULL(tp.MRP, 0), 2)
                   ORDER BY tp.Sl
               ) AS line_no
        FROM trans_trading_products tp
        WHERE tp.Trading_Id = pTrading_Id
    ) p
    JOIN mst_product i ON i.Prod_Id = p.Prod_Id
    LEFT JOIN (
        SELECT
            st.Prod_Id,
            st.Quantity,
            ROUND(st.Rate, 2) AS Rate,
            ROUND(IFNULL(st.MRP, 0), 2) AS MRP,
            st.Pack_Date,
            st.Barcode,
            ROW_NUMBER() OVER (
                PARTITION BY st.Prod_Id, st.Quantity, ROUND(st.Rate, 2), ROUND(IFNULL(st.MRP, 0), 2)
                ORDER BY st.Stock_Id
            ) AS line_no
        FROM trns_stockinout st
        WHERE st.Type_Id = pTrading_Id
    ) s ON s.Prod_Id = p.Prod_Id
       AND s.Quantity = p.Item_Qty
       AND s.Rate = ROUND(p.Item_Rate, 2)
       AND s.MRP = ROUND(IFNULL(p.MRP, 0), 2)
       AND s.line_no = p.line_no
    ORDER BY p.Sl;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_CORE_SALE_RETURN_OPTION_TYPES;
DELIMITER $$
CREATE PROCEDURE USP_GET_CORE_SALE_RETURN_OPTION_TYPES()
BEGIN

    SELECT
        MAX(CASE WHEN Value_Name = 'Sales Entry' THEN Value_Id END) AS SaleType,
        MAX(CASE WHEN Value_Name = 'Sales Return Entry' THEN Value_Id END) AS ReturnType
    FROM smartinventory_core.mst_options
    WHERE Option_Id = 6;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_SEARCH_SALE_FOR_RETURN_BILL;
DELIMITER $$
CREATE PROCEDURE USP_SEARCH_SALE_FOR_RETURN_BILL(IN pSale_Type TINYINT,
    IN pReturn_Type TINYINT,
    IN pBillLike VARCHAR(120),
    IN pBranch_Id INT,
    IN pFromDate DATE,
    IN pToDate DATE,
    IN pParty_Id INT,
    IN pUseDateRange TINYINT)
BEGIN

    SELECT
        m.Trading_Id AS Sale_Id,
        m.Invoice_No,
        m.Ref_No,
        m.Invoice_Date,
        m.Party_Id,
        CASE
            WHEN IFNULL(m.Party_Id, 0) = 0 THEN 'Outside / Cash'
            ELSE UDF_GET_PARTY_NAME(m.Party_Id)
        END AS Party_Name,
        m.Net_Amt
    FROM trans_trading m
    WHERE m.Tranding_Type = pSale_Type
      AND m.Status_Cd = 1
      AND IFNULL(m.Agent_Id, 0) = 0
      AND (m.Invoice_No LIKE pBillLike OR m.Ref_No LIKE pBillLike)
      AND (pBranch_Id = 0 OR m.Branch_Id = pBranch_Id)
      AND (pUseDateRange = 0 OR m.Invoice_Date BETWEEN pFromDate AND pToDate)
      AND (pParty_Id = 0 OR m.Party_Id = pParty_Id)
      AND EXISTS (
            SELECT 1
            FROM trans_trading_products p
            WHERE p.Trading_Id = m.Trading_Id
              AND (
                    IFNULL(p.Item_Qty, 0)
                    - IFNULL((
                        SELECT SUM(rp.Item_Qty)
                        FROM trans_trading r
                        INNER JOIN trans_trading_products rp
                            ON rp.Trading_Id = r.Trading_Id
                        WHERE r.Tranding_Type = pReturn_Type
                          AND r.Status_Cd = 1
                          AND IFNULL(r.Agent_Id, 0) = 0
                          AND IFNULL(r.Party_Id, 0) = IFNULL(m.Party_Id, 0)
                          AND rp.Prod_Id = p.Prod_Id
                          AND (r.Ref_No = m.Invoice_No OR r.Ref_No = m.Ref_No)
                    ), 0)
                  ) > 0
          )
    ORDER BY m.Invoice_Date DESC, m.Trading_Id DESC
    LIMIT 200;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_GENERAL_VOUCHER_DTLS;
DELIMITER $$
CREATE PROCEDURE USP_GET_GENERAL_VOUCHER_DTLS(IN pVoucher_Id INT)
BEGIN

    SELECT m.Voucher_Id,
           DATE_FORMAT(m.Vou_Date, '%Y-%m-%d') AS Vou_Date,
           m.Vou_Type,
           m.Vou_Mode,
           m.Vou_No,
           m.Ref_Vou_No,
           m.Particulars,
           m.Instrument_No,
           dr.GlHead_Id AS Debit_Ledger,
           cr.GlHead_Id AS Credit_Ledger,
           dr.Vou_Amount AS Amount
    FROM trans_voucher_master m
    INNER JOIN trans_voucher_details dr
        ON dr.Voucher_Id = m.Voucher_Id AND dr.Trans_Type = 'D'
    INNER JOIN trans_voucher_details cr
        ON cr.Voucher_Id = m.Voucher_Id AND cr.Trans_Type = 'C'
    WHERE m.Voucher_Id = pVoucher_Id
      AND m.Trans_Type = 9
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_DEFAULT_CASH_LEDGER;
DELIMITER $$
CREATE PROCEDURE USP_GET_DEFAULT_CASH_LEDGER()
BEGIN

    SELECT IFNULL(
        (SELECT Cash_Ledg FROM mst_default_ledger WHERE Cash_Ledg IS NOT NULL LIMIT 1),
        (SELECT Account_Id FROM mst_acct_glhead WHERE Account_For = 'C' LIMIT 1)
    ) AS Cash_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_DEFAULT_SUNDRY_LEDGER_IDS;
DELIMITER $$
CREATE PROCEDURE USP_GET_DEFAULT_SUNDRY_LEDGER_IDS()
BEGIN

    SELECT IFNULL(Debit_Ledger, 0) AS Debit_Ledger, IFNULL(Credit_Ledger, 0) AS Credit_Ledger
    FROM mst_default_ledger LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_USER_SCROLL_COUNTER_OPENING;
DELIMITER $$
CREATE PROCEDURE USP_RPT_USER_SCROLL_COUNTER_OPENING(IN pAsOnDate DATE,
    IN pUser_Id INT)
BEGIN

    SELECT IFNULL(SUM(b.balance), 0) AS opening
    FROM trn_counter_balance b
    INNER JOIN (
        SELECT t.counter_id, MAX(t.id) AS id
        FROM trn_counter_balance t
        INNER JOIN (
            SELECT counter_id, MAX(`date`) AS d
            FROM trn_counter_balance
            WHERE `date` <= pAsOnDate
              AND (pUser_Id = 0 OR counter_id = pUser_Id)
            GROUP BY counter_id
        ) d ON d.counter_id = t.counter_id AND t.`date` = d.d
        GROUP BY t.counter_id
    ) x ON x.id = b.id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_USER_SCROLL_CASH_MOVE;
DELIMITER $$
CREATE PROCEDURE USP_RPT_USER_SCROLL_CASH_MOVE(IN pCash_Id INT,
    IN pYear_Id INT,
    IN pAsOnDate DATE,
    IN pUser_Id INT)
BEGIN

    SELECT
        IFNULL(SUM(CASE WHEN cash.Trans_Type = 'D' THEN cash.Vou_Amount ELSE 0 END), 0) AS cash_in,
        IFNULL(SUM(CASE WHEN cash.Trans_Type = 'C' THEN cash.Vou_Amount ELSE 0 END), 0) AS cash_out
    FROM trans_voucher_master m
    INNER JOIN trans_voucher_details cash
       ON cash.Voucher_Id = m.Voucher_Id
      AND cash.GlHead_Id = pCash_Id
    WHERE m.Year_Id = pYear_Id
      AND IFNULL(m.Status, 2) = 2
      AND m.Vou_Date = pAsOnDate
      AND (pUser_Id = 0 OR m.Created_By = pUser_Id)
      AND cash.Trans_Type IN ('D', 'C');

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_USER_SCROLL_VOUCHERS;
DELIMITER $$
CREATE PROCEDURE USP_RPT_USER_SCROLL_VOUCHERS(IN pDebtor_Id INT,
    IN pCreditor_Id INT,
    IN pYear_Id INT,
    IN pAsOnDate DATE,
    IN pUser_Id INT)
BEGIN

    SELECT
        m.Voucher_Id,
        IFNULL(m.Vou_No, '') AS Vou_No,
        IFNULL(m.Particulars, '') AS Particulars,
        IFNULL(m.Ref_Vou_No, '') AS Ref_Vou_No,
        MIN(t.Trading_Id) AS Trading_Id,
        MIN(t.Tranding_Type) AS Tranding_Type,
        MIN(t.Invoice_No) AS Invoice_No,
        MIN(t.Net_Amt) AS Net_Amt,
        MIN(IFNULL(p.Party_Name, '')) AS Party_Name,
        MIN(IFNULL(a.Agent_Name, '')) AS Agent_Name,
        IFNULL(SUM(CASE WHEN g.Account_For = 'C' AND d.Trans_Type = 'D' THEN d.Vou_Amount ELSE 0 END), 0) AS Receipt_Cash,
        IFNULL(SUM(CASE WHEN g.Account_For = 'B' AND d.Trans_Type = 'D' THEN d.Vou_Amount ELSE 0 END), 0) AS Receipt_Bank,
        IFNULL(SUM(CASE WHEN g.Account_For = 'C' AND d.Trans_Type = 'C' THEN d.Vou_Amount ELSE 0 END), 0) AS Payment_Cash,
        IFNULL(SUM(CASE WHEN g.Account_For = 'B' AND d.Trans_Type = 'C' THEN d.Vou_Amount ELSE 0 END), 0) AS Payment_Bank,
        IFNULL(SUM(CASE WHEN d.GlHead_Id = pDebtor_Id AND d.Trans_Type = 'D' THEN d.Vou_Amount ELSE 0 END), 0) AS Debtor_Dr,
        IFNULL(SUM(CASE WHEN d.GlHead_Id = pCreditor_Id AND d.Trans_Type = 'C' THEN d.Vou_Amount ELSE 0 END), 0) AS Creditor_Cr,
        IFNULL(m.Vou_Type, 0) AS Vou_Type,
        IFNULL(MAX(d.Vou_Amount), 0) AS Vou_Amount,
        IFNULL((
            SELECT g2.Account_Desc
            FROM trans_voucher_details d2
            INNER JOIN mst_acct_glhead g2 ON g2.Account_Id = d2.GlHead_Id
            WHERE d2.Voucher_Id = m.Voucher_Id
              AND IFNULL(g2.Account_For, 'O') NOT IN ('C', 'B')
            ORDER BY d2.Vou_Amount DESC, d2.VouDtls_Id
            LIMIT 1
        ), '') AS Ledger_Name
    FROM trans_voucher_master m
    LEFT JOIN trans_voucher_details d ON d.Voucher_Id = m.Voucher_Id
    LEFT JOIN mst_acct_glhead g ON g.Account_Id = d.GlHead_Id
    LEFT JOIN trans_trading t ON t.Voucher_Id = m.Voucher_Id
    LEFT JOIN mst_party p ON p.Party_Id = t.Party_Id
    LEFT JOIN mst_agent a ON a.Agent_Id = t.Agent_Id
    WHERE m.Year_Id = pYear_Id
      AND IFNULL(m.Status, 2) = 2
      AND m.Vou_Date = pAsOnDate
      AND (pUser_Id = 0 OR m.Created_By = pUser_Id)
    GROUP BY m.Voucher_Id, m.Vou_No, m.Particulars, m.Ref_Vou_No, m.Vou_Type
    ORDER BY m.Voucher_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_USER_SCROLL_TRADING_PRODUCTS;
DELIMITER $$
CREATE PROCEDURE USP_RPT_USER_SCROLL_TRADING_PRODUCTS(IN pTrading_Id_Csv TEXT)
BEGIN

    SELECT tp.Trading_Id, IFNULL(p.Prod_ShortNm, '') AS Item_Name,
           IFNULL(tp.Gst_Code, '') AS HSN_No,
           IFNULL(UDF_GET_UNIT_NAME(tp.Unit_Id), '') AS Unit_Name,
           IFNULL(tp.Item_Qty, 0) AS Item_Qty,
           IFNULL(tp.Item_Rate, 0) AS Item_Rate,
           IFNULL(tp.MRP, 0) AS MRP,
           IFNULL(tp.Disc_Prcnt, 0) AS Disc_Prcnt,
           IFNULL(tp.Taxable_Amt, 0) AS Taxable_Amt,
           (IFNULL(tp.SGST_Prcnt, 0) + IFNULL(tp.CGST_Prcnt, 0)) AS GST_Prcnt,
           (IFNULL(tp.SGST_Amt, 0) + IFNULL(tp.CGST_Amt, 0)) AS GST_Amt,
           IFNULL(tp.Net_Amt, 0) AS Net_Amt
    FROM trans_trading_products tp
    LEFT JOIN mst_product p ON p.Prod_Id = tp.Prod_Id
    WHERE IFNULL(pTrading_Id_Csv, '') <> ''
      AND FIND_IN_SET(tp.Trading_Id, pTrading_Id_Csv) > 0
    ORDER BY tp.Trading_Id, tp.Sl;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_CASH_BOOK_OPENING;
DELIMITER $$
CREATE PROCEDURE USP_RPT_CASH_BOOK_OPENING(IN pCash_Id INT,
    IN pYear_Id INT,
    IN pFromDate DATE)
BEGIN

    SELECT IFNULL(SUM(CASE WHEN d.Trans_Type = 'D' THEN d.Vou_Amount ELSE -d.Vou_Amount END), 0) AS Amt
    FROM trans_voucher_details d
    INNER JOIN trans_voucher_master m ON m.Voucher_Id = d.Voucher_Id
    WHERE d.GlHead_Id = pCash_Id
      AND m.Year_Id = pYear_Id
      AND IFNULL(m.Status, 2) = 2
      AND m.Vou_Date < pFromDate;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_CASH_BOOK_LINES;
DELIMITER $$
CREATE PROCEDURE USP_RPT_CASH_BOOK_LINES(IN pCash_Id INT,
    IN pYear_Id INT,
    IN pFromDate DATE,
    IN pToDate DATE)
BEGIN

    SELECT
        m.Voucher_Id,
        m.Vou_Date,
        IFNULL(m.Vou_No, '') AS Vou_No,
        IFNULL(m.Trans_Type, 0) AS Trans_Type,
        IFNULL(m.Type_Id, 0) AS Type_Id,
        IFNULL(m.Vou_Type, 0) AS Vou_Type,
        CASE WHEN cash.Trans_Type = 'D' THEN 'R' ELSE 'P' END AS Side,
        IFNULL(tr.Tranding_Type, 0) AS Tranding_Type,
        IFNULL(pty.Party_Type, 0) AS Party_Type,
        IFNULL(pty.Party_Name, '') AS Party_Name,
        IFNULL((
            SELECT g.Account_Desc
            FROM trans_voucher_details d
            LEFT JOIN mst_acct_glhead g ON g.Account_Id = d.GlHead_Id
            WHERE d.Voucher_Id = m.Voucher_Id
              AND d.GlHead_Id <> pCash_Id
            ORDER BY d.Vou_Amount DESC, d.VouDtls_Id
            LIMIT 1
        ), '') AS Gl_Head,
        IFNULL(NULLIF(TRIM(m.Particulars), ''), IFNULL(m.Ref_Vou_No, '')) AS Particulars,
        IFNULL(cash.Vou_Amount, 0) AS Amount
    FROM trans_voucher_master m
    INNER JOIN trans_voucher_details cash
       ON cash.Voucher_Id = m.Voucher_Id
      AND cash.GlHead_Id = pCash_Id
    LEFT JOIN (
       SELECT Voucher_Id, MIN(Tranding_Type) AS Tranding_Type
       FROM trans_trading
       WHERE Voucher_Id IS NOT NULL
       GROUP BY Voucher_Id
    ) tr ON tr.Voucher_Id = m.Voucher_Id
    LEFT JOIN mst_party pty
       ON pty.Party_Id = m.Type_Id
      AND m.Trans_Type = 9
      AND IFNULL(m.Type_Id, 0) > 0
    WHERE m.Year_Id = pYear_Id
      AND IFNULL(m.Status, 2) = 2
      AND m.Vou_Date BETWEEN pFromDate AND pToDate
    ORDER BY m.Vou_Date, m.Voucher_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_CASH_ACCOUNT_LINES;
DELIMITER $$
CREATE PROCEDURE USP_RPT_CASH_ACCOUNT_LINES(IN pYear_Id INT,
    IN pFromDate DATE,
    IN pToDate DATE)
BEGIN

    SELECT
        IFNULL(m.Vou_Mode, 0) AS Vou_Mode,
        d.Trans_Type AS DrCr,
        IFNULL(d.GlHead_Id, 0) AS GlHead_Id,
        IFNULL(g.Account_Code, '') AS Account_Code,
        IFNULL(g.Account_Desc, '') AS Gl_Head,
        IFNULL(d.Vou_Amount, 0) AS Amount
    FROM trans_voucher_master m
    INNER JOIN trans_voucher_details d ON d.Voucher_Id = m.Voucher_Id
    LEFT JOIN mst_acct_glhead g ON g.Account_Id = d.GlHead_Id
    WHERE m.Year_Id = pYear_Id
      AND IFNULL(m.Status, 2) = 2
      AND m.Vou_Date BETWEEN pFromDate AND pToDate;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_STOCK_BARCODE_BARCODED;
DELIMITER $$
CREATE PROCEDURE USP_RPT_STOCK_BARCODE_BARCODED(IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        b.Barcode,
        b.MRP,
        (b.Avil_Qnty + CASE WHEN c.Barcode_Count = 1 THEN IFNULL(u.Unbar_Qnty, 0) ELSE 0 END) AS Avil_Qnty
    FROM (
        SELECT
            s.Barcode AS Barcode,
            CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Avil_Qnty
        FROM trns_stockinout s
        WHERE s.Prod_Id = pProd_Id
          AND s.InOut_Date <= pAsOnDate
          AND IFNULL(s.Barcode, 0) <> 0
        GROUP BY s.Barcode
    ) b
    LEFT JOIN (
        SELECT MRP, COUNT(*) AS Barcode_Count
        FROM (
            SELECT
                s.Barcode,
                CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP
            FROM trns_stockinout s
            WHERE s.Prod_Id = pProd_Id
              AND s.InOut_Date <= pAsOnDate
              AND IFNULL(s.Barcode, 0) <> 0
            GROUP BY s.Barcode
        ) m
        GROUP BY MRP
    ) c ON c.MRP = b.MRP
    LEFT JOIN (
        SELECT
            CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Unbar_Qnty
        FROM trns_stockinout s
        WHERE s.Prod_Id = pProd_Id
          AND s.InOut_Date <= pAsOnDate
          AND IFNULL(s.Barcode, 0) = 0
        GROUP BY CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2))
    ) u ON u.MRP = b.MRP
    ORDER BY b.MRP DESC, b.Barcode DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_STOCK_BARCODE_LEFTOVER;
DELIMITER $$
CREATE PROCEDURE USP_RPT_STOCK_BARCODE_LEFTOVER(IN pProd_Id INT,
    IN pAsOnDate DATE)
BEGIN

    SELECT
        0 AS Barcode,
        u.MRP,
        u.Unbar_Qnty AS Avil_Qnty
    FROM (
        SELECT
            CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Unbar_Qnty
        FROM trns_stockinout s
        WHERE s.Prod_Id = pProd_Id
          AND s.InOut_Date <= pAsOnDate
          AND IFNULL(s.Barcode, 0) = 0
        GROUP BY CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2))
    ) u
    LEFT JOIN (
        SELECT MRP, COUNT(*) AS Barcode_Count
        FROM (
            SELECT
                s.Barcode,
                CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP
            FROM trns_stockinout s
            WHERE s.Prod_Id = pProd_Id
              AND s.InOut_Date <= pAsOnDate
              AND IFNULL(s.Barcode, 0) <> 0
            GROUP BY s.Barcode
        ) m
        GROUP BY MRP
    ) c ON c.MRP = u.MRP
    WHERE IFNULL(c.Barcode_Count, 0) <> 1
    ORDER BY u.MRP DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_CLOSING_BARCODE_STOCK;
DELIMITER $$
CREATE PROCEDURE USP_RPT_CLOSING_BARCODE_STOCK(IN pAsOnDate DATE,
    IN pProd_Id INT)
BEGIN

    SELECT
        b.Prod_Id,
        b.Barcode,
        b.MRP,
        (b.Avil_Qnty + CASE WHEN c.Barcode_Count = 1 THEN IFNULL(u.Unbar_Qnty, 0) ELSE 0 END) AS Avil_Qnty
    FROM (
        SELECT
            s.Prod_Id,
            s.Barcode AS Barcode,
            CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Avil_Qnty
        FROM trns_stockinout s
        WHERE s.InOut_Date <= pAsOnDate
          AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
          AND IFNULL(s.Barcode, 0) <> 0
        GROUP BY s.Prod_Id, s.Barcode
    ) b
    LEFT JOIN (
        SELECT Prod_Id, MRP, COUNT(*) AS Barcode_Count
        FROM (
            SELECT
                s.Prod_Id,
                s.Barcode,
                CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP
            FROM trns_stockinout s
            WHERE s.InOut_Date <= pAsOnDate
              AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
              AND IFNULL(s.Barcode, 0) <> 0
            GROUP BY s.Prod_Id, s.Barcode
        ) m
        GROUP BY Prod_Id, MRP
    ) c ON c.Prod_Id = b.Prod_Id AND c.MRP = b.MRP
    LEFT JOIN (
        SELECT
            s.Prod_Id,
            CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Unbar_Qnty
        FROM trns_stockinout s
        WHERE s.InOut_Date <= pAsOnDate
          AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
          AND IFNULL(s.Barcode, 0) = 0
        GROUP BY s.Prod_Id, CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2))
    ) u ON u.Prod_Id = b.Prod_Id AND u.MRP = b.MRP
    ORDER BY b.MRP DESC, b.Barcode DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_CLOSING_BARCODE_LEFTOVER;
DELIMITER $$
CREATE PROCEDURE USP_RPT_CLOSING_BARCODE_LEFTOVER(IN pAsOnDate DATE,
    IN pProd_Id INT)
BEGIN

    SELECT
        u.Prod_Id,
        0 AS Barcode,
        u.MRP,
        u.Unbar_Qnty AS Avil_Qnty
    FROM (
        SELECT
            s.Prod_Id,
            CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2)) AS MRP,
            IFNULL(SUM(CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END), 0) AS Unbar_Qnty
        FROM trns_stockinout s
        WHERE s.InOut_Date <= pAsOnDate
          AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
          AND IFNULL(s.Barcode, 0) = 0
        GROUP BY s.Prod_Id, CAST(IFNULL(s.MRP, 0) AS DECIMAL(10,2))
    ) u
    LEFT JOIN (
        SELECT Prod_Id, MRP, COUNT(*) AS Barcode_Count
        FROM (
            SELECT
                s.Prod_Id,
                s.Barcode,
                CAST(IFNULL(MAX(CASE WHEN s.Stock_Type IN (1, 2) THEN s.MRP END), MAX(s.MRP)) AS DECIMAL(10,2)) AS MRP
            FROM trns_stockinout s
            WHERE s.InOut_Date <= pAsOnDate
              AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
              AND IFNULL(s.Barcode, 0) <> 0
            GROUP BY s.Prod_Id, s.Barcode
        ) m
        GROUP BY Prod_Id, MRP
    ) c ON c.Prod_Id = u.Prod_Id AND c.MRP = u.MRP
    WHERE IFNULL(c.Barcode_Count, 0) <> 1
    ORDER BY u.MRP DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_STOCK_STATEMENT_PRODUCTS;
DELIMITER $$
CREATE PROCEDURE USP_RPT_STOCK_STATEMENT_PRODUCTS(IN pFromDate DATE,
    IN pToDate DATE,
    IN pCat_Id INT,
    IN pSubCat_Id INT)
BEGIN

    SELECT
        p.Prod_Id,
        p.Prod_Code,
        p.Prod_ShortNm,
        IFNULL(UDF_GET_CAT_SUB_NAME(p.Cate_Id, 1), '') AS Cate_Name,
        IFNULL(UDF_GET_UNIT_NAME(p.Unit_Id), '') AS Unit_Name,
        x.Opening_Qty,
        x.Purchase_Qty,
        x.Purchase_Value,
        x.Purchase_Return_Qty,
        x.Purchase_Return_Value,
        x.Sold_Qty,
        x.Sold_Value,
        x.Sold_Return_Qty,
        x.Sold_Return_Value,
        x.Damage_Qty,
        x.Damage_Value
    FROM (
        SELECT
            s.Prod_Id,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date < pFromDate THEN 
            CASE
                WHEN s.Stock_Type IN (1, 2, 6) THEN s.Quantity
                WHEN s.Stock_Type = 8 AND NOT EXISTS (
                    SELECT 1 FROM trans_agent_stock a WHERE a.TrnsStock_Id = s.Stock_Id
                ) THEN s.Quantity
                WHEN s.Stock_Type IN (3, 4, 7, 9) THEN -s.Quantity
                ELSE 0
            END
                WHEN s.Stock_Type = 1 AND s.InOut_Date BETWEEN pFromDate AND pToDate THEN s.Quantity
                ELSE 0
            END), 0) AS Opening_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 2 THEN s.Quantity
                ELSE 0
            END), 0) AS Purchase_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 2 THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
                ELSE 0
            END), 0) AS Purchase_Value,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 7 THEN s.Quantity
                ELSE 0
            END), 0) AS Purchase_Return_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 7 THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
                ELSE 0
            END), 0) AS Purchase_Return_Value,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate
                 AND (
                    s.Stock_Type = 3
                    OR (
                        s.Stock_Type = 5
                        AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
                        AND (t.Settle_Date IS NULL OR t.Settle_Date <= pToDate)
                    )
                 ) THEN s.Quantity
                ELSE 0
            END), 0) AS Sold_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate
                 AND (
                    s.Stock_Type = 3
                    OR (
                        s.Stock_Type = 5
                        AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
                        AND (t.Settle_Date IS NULL OR t.Settle_Date <= pToDate)
                    )
                 ) THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
                ELSE 0
            END), 0) AS Sold_Value,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 8 THEN s.Quantity
                ELSE 0
            END), 0) AS Sold_Return_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 8 THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
                ELSE 0
            END), 0) AS Sold_Return_Value,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 9 THEN s.Quantity
                ELSE 0
            END), 0) AS Damage_Qty,
            IFNULL(SUM(CASE
                WHEN s.InOut_Date BETWEEN pFromDate AND pToDate AND s.Stock_Type = 9 THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
                ELSE 0
            END), 0) AS Damage_Value
        FROM trns_stockinout s
        LEFT JOIN trans_trading t
            ON t.Trading_Id = s.Type_Id
           AND s.Stock_Type = 5
        WHERE s.InOut_Date <= pToDate
        GROUP BY s.Prod_Id
    ) x
    INNER JOIN mst_product p ON p.Prod_Id = x.Prod_Id
    WHERE (pCat_Id = 0 OR p.Cate_Id = pCat_Id)
      AND (pSubCat_Id = 0 OR p.SubCate_Id = pSubCat_Id)
    ORDER BY p.Prod_ShortNm, p.Prod_Code;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_STOCK_STATEMENT_AGENT;
DELIMITER $$
CREATE PROCEDURE USP_RPT_STOCK_STATEMENT_AGENT(IN pToDate DATE,
    IN pCat_Id INT,
    IN pSubCat_Id INT)
BEGIN

    SELECT
        s.Prod_Id,
        IFNULL(SUM(CASE
            WHEN s.Stock_Type = 4 THEN s.Quantity
            WHEN s.Stock_Type = 6 THEN -s.Quantity
            WHEN s.Stock_Type = 5
             AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
             AND (t.Settle_Date IS NULL OR t.Settle_Date <= pToDate) THEN -s.Quantity
            ELSE 0
        END), 0) AS Agent_Qty,
        IFNULL(SUM(CASE
            WHEN s.Stock_Type = 4 THEN s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
            WHEN s.Stock_Type = 6 THEN -s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
            WHEN s.Stock_Type = 5
             AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
             AND (t.Settle_Date IS NULL OR t.Settle_Date <= pToDate) THEN -s.Quantity * (CASE WHEN IFNULL(s.MRP, 0) > 0 THEN s.MRP ELSE IFNULL(s.Rate, 0) END)
            ELSE 0
        END), 0) AS Agent_Value
    FROM trns_stockinout s
    INNER JOIN mst_product p ON p.Prod_Id = s.Prod_Id
    LEFT JOIN trans_trading t
        ON t.Trading_Id = s.Type_Id
       AND s.Stock_Type = 5
    WHERE s.InOut_Date <= pToDate
      AND s.Stock_Type IN (4, 5, 6)
      AND (pCat_Id = 0 OR p.Cate_Id = pCat_Id)
      AND (pSubCat_Id = 0 OR p.SubCate_Id = pSubCat_Id)
    GROUP BY s.Prod_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_PURCHASE_RATES_BY_BARCODES;
DELIMITER $$
CREATE PROCEDURE USP_GET_PURCHASE_RATES_BY_BARCODES(IN pBarcode_Csv TEXT)
BEGIN

    SELECT Barcode, Rate
    FROM trns_stockinout
    WHERE Stock_Type IN (1, 2)
      AND IFNULL(pBarcode_Csv, '') <> ''
      AND FIND_IN_SET(Barcode, pBarcode_Csv) > 0
    ORDER BY Stock_Type DESC, Stock_Id DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_DAMAGE_LATEST_TRADING_ID;
DELIMITER $$
CREATE PROCEDURE USP_GET_DAMAGE_LATEST_TRADING_ID(IN pInvoice_Date DATE,
    IN pCreated_By INT)
BEGIN

    SELECT Trading_Id
    FROM trans_trading
    WHERE Tranding_Type = 6
      AND Invoice_Date = pInvoice_Date
      AND Created_By = pCreated_By
    ORDER BY Trading_Id DESC
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_DAMAGE_STOCK_BY_TRADING;
DELIMITER $$
CREATE PROCEDURE USP_GET_DAMAGE_STOCK_BY_TRADING(IN pTrading_Id INT)
BEGIN

    SELECT Prod_Id, Barcode, Quantity, Rate, MRP
    FROM trns_stockinout
    WHERE Stock_Type = 9
      AND Type_Id = pTrading_Id
    ORDER BY Stock_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_PRODUCT_CODE;
DELIMITER $$
CREATE PROCEDURE USP_GET_PRODUCT_CODE(IN pProd_Id INT)
BEGIN

    SELECT Prod_Code FROM mst_product WHERE Prod_Id = pProd_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_PRODUCT_SHORT_NAME;
DELIMITER $$
CREATE PROCEDURE USP_GET_PRODUCT_SHORT_NAME(IN pProd_Id INT)
BEGIN

    SELECT Prod_ShortNm FROM mst_product WHERE Prod_Id = pProd_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_VALIDATE_AGENT_CUSTOMER;
DELIMITER $$
CREATE PROCEDURE USP_VALIDATE_AGENT_CUSTOMER(IN pParty_Id INT,
    IN pAgent_Id INT)
BEGIN

    SELECT Party_Id FROM mst_party
    WHERE Party_Id = pParty_Id AND Party_Type = 2 AND Cust_Agent_Id = pAgent_Id
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_VALIDATE_AGENT_PAYMENT_OWNERSHIP;
DELIMITER $$
CREATE PROCEDURE USP_VALIDATE_AGENT_PAYMENT_OWNERSHIP(IN pAgent_Id INT,
    IN pPayment_Id INT)
BEGIN

    SELECT t.Id
    FROM trn_party_trans t
    INNER JOIN mst_party p
            ON p.Party_Id = t.Party_Id
           AND p.Party_Type = 2
           AND p.Cust_Agent_Id = pAgent_Id
    WHERE t.Id = pPayment_Id
      AND t.Trans_Type = 'C'
      AND IFNULL(t.Trading_Id, 0) = 0
      AND t.Trans_Mode IN (1, 2)
      AND t.Created_By = pAgent_Id
      AND IFNULL(t.Txn_Id, 0) = 0
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_PAYMENT_DTLS;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_PAYMENT_DTLS(IN pAgent_Id INT,
    IN pPayment_Id INT)
BEGIN

    SELECT t.Id AS Payment_Id,
           t.Id AS Voucher_Id,
           t.Trans_Date AS Vou_Date,
           t.Party_Id,
           t.Amount,
           t.Trans_Mode AS Vou_Mode,
           t.Txn_Id,
           CASE
               WHEN LOCATE('|', t.Remarks) > 0
               THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', 1))
               ELSE COALESCE(m.Vou_No, CONCAT('ACP-', t.Id))
           END AS Vou_No,
           CASE
               WHEN (LENGTH(t.Remarks) - LENGTH(REPLACE(t.Remarks, '|', ''))) >= 2
               THEN TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(t.Remarks, '|', 2), '|', -1))
               ELSE ''
           END AS Ref_Vou_No,
           CASE
               WHEN (LENGTH(t.Remarks) - LENGTH(REPLACE(t.Remarks, '|', ''))) >= 2
               THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', -1))
               WHEN LOCATE('|', t.Remarks) > 0
               THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', -1))
               ELSE IFNULL(t.Remarks, '')
           END AS Particulars,
           CASE WHEN IFNULL(t.Txn_Id, 0) = 0 THEN 1 ELSE 0 END AS Can_Edit
    FROM trn_party_trans t
    INNER JOIN mst_party p
            ON p.Party_Id = t.Party_Id
           AND p.Party_Type = 2
           AND p.Cust_Agent_Id = pAgent_Id
    LEFT JOIN trans_voucher_master m
           ON m.Voucher_Id = t.Txn_Id
    WHERE t.Id = pPayment_Id
      AND t.Trans_Type = 'C'
      AND IFNULL(t.Trading_Id, 0) = 0
      AND t.Trans_Mode IN (1, 2)
      AND t.Created_By = pAgent_Id
    LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_PAYMENT_LIST;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_PAYMENT_LIST(IN pAgent_Id INT)
BEGIN

    SELECT t.Id AS Payment_Id,
           t.Id AS Voucher_Id,
           DATE_FORMAT(t.Trans_Date, '%d-%m-%Y') AS Vou_Date_Disp,
           t.Trans_Date AS Vou_Date,
           CASE
               WHEN LOCATE('|', t.Remarks) > 0
               THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', 1))
               ELSE COALESCE(m.Vou_No, CONCAT('ACP-', t.Id))
           END AS Vou_No,
           p.Party_Name,
           t.Amount,
           CASE WHEN IFNULL(t.Txn_Id, 0) = 0 THEN 1 ELSE 0 END AS Can_Edit
    FROM trn_party_trans t
    INNER JOIN mst_party p
            ON p.Party_Id = t.Party_Id
           AND p.Party_Type = 2
           AND p.Cust_Agent_Id = pAgent_Id
    LEFT JOIN trans_voucher_master m
           ON m.Voucher_Id = t.Txn_Id
    WHERE t.Trans_Type = 'C'
      AND IFNULL(t.Trading_Id, 0) = 0
      AND t.Trans_Mode IN (1, 2)
      AND t.Created_By = pAgent_Id
    ORDER BY t.Id DESC
    LIMIT 10;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_BARCODE_MAX_MRP;
DELIMITER $$
CREATE PROCEDURE USP_GET_BARCODE_MAX_MRP(IN pBarcode VARCHAR(30))
BEGIN

    SELECT IFNULL(MAX(MRP), 0) AS MRP
    FROM trns_stockinout
    WHERE Barcode = pBarcode AND Stock_Type IN (1, 2);

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_PURCHASE_BARCODES_FOR_RETURN;
DELIMITER $$
CREATE PROCEDURE USP_GET_PURCHASE_BARCODES_FOR_RETURN(IN pParty_Id INT,
    IN pAsOnDate DATE,
    IN pProd_Id INT,
    IN pBarcode VARCHAR(30),
    IN pExclude_Id INT)
BEGIN

    SELECT
        s.Barcode,
        CAST(IFNULL(MAX(s.MRP), 0) AS DECIMAL(10,2)) AS MRP,
        p.Prod_Id,
        IFNULL(p.Prod_Code, '') AS Prod_Code,
        p.Prod_ShortNm,
        p.Unit_Id,
        UDF_GET_UNIT_NAME(p.Unit_Id) AS Unit_Name,
        p.Gst_Id,
        IFNULL(c.Is_Fmcg, 0) + 0 AS Is_Fmcg,
        UDF_GET_ITEM_GST_DETAILS(p.Gst_Id) AS GST_Data,
        SUM(s.Quantity) AS Purchased_Qty,
        IFNULL(MAX(ret.Returned_Qty), 0) AS Returned_Qty,
        SUM(s.Quantity) - IFNULL(MAX(ret.Returned_Qty), 0) AS Remaining_Qty
    FROM trns_stockinout s
    INNER JOIN trans_trading t
        ON t.Trading_Id = s.Type_Id
       AND t.Tranding_Type = 2
    INNER JOIN mst_product p ON p.Prod_Id = s.Prod_Id
    LEFT JOIN mst_prod_category c ON c.Prd_CateId = p.Cate_Id
    LEFT JOIN (
        SELECT Barcode, SUM(Quantity) AS Returned_Qty
        FROM trns_stockinout
        WHERE Stock_Type = 7
          AND IFNULL(Barcode, 0) <> 0
          AND InOut_Date <= pAsOnDate
          AND (pExclude_Id = 0 OR IFNULL(Type_Id, 0) <> pExclude_Id)
        GROUP BY Barcode
    ) ret ON ret.Barcode = s.Barcode
    WHERE s.Stock_Type = 2
      AND IFNULL(s.Barcode, 0) <> 0
      AND t.Party_Id = pParty_Id
      AND s.InOut_Date <= pAsOnDate
      AND (pProd_Id = 0 OR s.Prod_Id = pProd_Id)
      AND (pBarcode = '' OR s.Barcode = pBarcode)
    GROUP BY s.Barcode, p.Prod_Id, p.Prod_Code, p.Prod_ShortNm, p.Unit_Id, p.Gst_Id, c.Is_Fmcg
    HAVING SUM(s.Quantity) - IFNULL(MAX(ret.Returned_Qty), 0) > 0
    ORDER BY MAX(s.Stock_Id) DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_ASSIGN_PURCHASE_RETURN_BARCODE;
DELIMITER $$
CREATE PROCEDURE USP_ASSIGN_PURCHASE_RETURN_BARCODE(IN pBarcode VARCHAR(30),
    IN pMrp DECIMAL(10,2),
    IN pProd_Id INT,
    IN pInOut_Date DATE)
BEGIN

    UPDATE trns_stockinout
    SET Barcode = pBarcode,
        MRP = CASE WHEN IFNULL(MRP, 0) = 0 THEN pMrp ELSE MRP END
    WHERE Stock_Type = 7
      AND Prod_Id = pProd_Id
      AND IFNULL(Barcode, 0) = 0
      AND InOut_Date = pInOut_Date
     ORDER BY Stock_Id ASC
     LIMIT 1;
    SELECT ROW_COUNT() AS Affected;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_ASSIGN_SALE_RETURN_BARCODE;
DELIMITER $$
CREATE PROCEDURE USP_ASSIGN_SALE_RETURN_BARCODE(IN pBarcode VARCHAR(30),
    IN pMrp DECIMAL(10,2),
    IN pProd_Id INT,
    IN pInOut_Date DATE)
BEGIN

    UPDATE trns_stockinout
    SET Barcode = pBarcode,
        MRP = CASE WHEN IFNULL(MRP, 0) = 0 THEN pMrp ELSE MRP END
    WHERE Stock_Type = 8
      AND Prod_Id = pProd_Id
      AND IFNULL(Barcode, 0) = 0
      AND InOut_Date = pInOut_Date
    ORDER BY Stock_Id ASC
    LIMIT 1;
    SELECT ROW_COUNT() AS Affected;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_ASSIGN_DAMAGE_BARCODE;
DELIMITER $$
CREATE PROCEDURE USP_ASSIGN_DAMAGE_BARCODE(IN pBarcode VARCHAR(30),
    IN pMrp DECIMAL(10,2),
    IN pTrading_Id INT,
    IN pProd_Id INT,
    IN pQuantity INT,
    IN pRate DECIMAL(10,2))
BEGIN

    UPDATE trns_stockinout
       SET Barcode = pBarcode,
           MRP = CASE WHEN IFNULL(MRP, 0) = 0 THEN pMrp ELSE MRP END
     WHERE Stock_Type = 9
       AND Type_Id = pTrading_Id
       AND Prod_Id = pProd_Id
       AND Quantity = pQuantity
       AND ROUND(IFNULL(Rate, 0), 2) = pRate
       AND IFNULL(Barcode, 0) = 0
     ORDER BY Stock_Id ASC
     LIMIT 1;
    SELECT ROW_COUNT() AS Affected;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_STOCK_SUMMARY_AGENT;
DELIMITER $$
CREATE PROCEDURE USP_GET_STOCK_SUMMARY_AGENT(IN pAsOnDate DATE,
    IN pCat_Id INT,
    IN pSubCat_Id INT)
BEGIN

    SELECT
        p.Prod_Id,
        p.Prod_Code,
        p.Prod_ShortNm,
        IFNULL(UDF_GET_CAT_SUB_NAME(p.Cate_Id, 1), '') AS Cate_Name,
        IFNULL(UDF_GET_UNIT_NAME(p.Unit_Id), '') AS Unit_Name,
        IFNULL(SUM(
            CASE
                WHEN s.Stock_Type = 4 THEN s.Quantity
                WHEN s.Stock_Type = 6 THEN -s.Quantity
                WHEN s.Stock_Type = 5 AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1 THEN -s.Quantity
                ELSE 0
            END
        ), 0) AS Agent_Qty
     FROM trns_stockinout s
     INNER JOIN mst_product p ON p.Prod_Id = s.Prod_Id
     LEFT JOIN trans_trading t
        ON t.Trading_Id = s.Type_Id
       AND s.Stock_Type = 5
     WHERE s.InOut_Date <= pAsOnDate
       AND s.Stock_Type IN (4, 5, 6)
       AND (pCat_Id = 0 OR p.Cate_Id = pCat_Id)
       AND (pSubCat_Id = 0 OR p.SubCate_Id = pSubCat_Id)
     GROUP BY p.Prod_Id, p.Prod_Code, p.Prod_ShortNm, p.Cate_Id, p.Unit_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_PURCHASE_REGISTER;
DELIMITER $$
CREATE PROCEDURE USP_RPT_PURCHASE_REGISTER(IN pFrm DATE,
    IN pTo DATE,
    IN pParty_Id INT,
    IN pBranch_Id INT,
    IN pGst_Filter TINYINT)
BEGIN

    SELECT
        m.Trading_Id,
        m.Invoice_No,
        m.Invoice_Date,
        CASE IFNULL(m.Pay_Mode, 1)
            WHEN 1 THEN 'Cash'
            WHEN 2 THEN 'Bank'
            WHEN 3 THEN 'Credit'
            ELSE ''
        END AS Pay_Mode,
        IFNULL(pt.Party_Name, '') AS Party_Name,
        '' AS Agent_Name,
        IFNULL(i.Prod_ShortNm, '') AS Item_Name,
        IFNULL(tp.Gst_Code, '') AS HSN_No,
        IFNULL(tp.Item_Qty, 0) AS Item_Qty,
        IFNULL(UDF_GET_UNIT_NAME(tp.Unit_Id), '') AS Unit_Name,
        IFNULL(tp.Item_Rate, 0) AS Item_Rate,
        IFNULL(tp.Item_Total, 0) AS Item_Total,
        (IFNULL(tp.SGST_Prcnt, 0) + IFNULL(tp.CGST_Prcnt, 0)) AS GST_Prcnt,
        (IFNULL(tp.SGST_Amt, 0) + IFNULL(tp.CGST_Amt, 0)) AS GST_Amt,
        IFNULL(m.Round_Off, 0) AS Round_Off,
        IFNULL(tp.Net_Amt, 0) AS Net_Amt
     FROM trans_trading m
     INNER JOIN trans_trading_products tp ON tp.Trading_Id = m.Trading_Id
     INNER JOIN mst_product i ON i.Prod_Id = tp.Prod_Id
     LEFT JOIN mst_party pt ON pt.Party_Id = m.Party_Id
     WHERE m.Tranding_Type = 2
       AND IFNULL(m.Status_Cd, 1) = 1
       AND m.Invoice_Date BETWEEN pFrm AND pTo
       AND (pParty_Id = 0 OR m.Party_Id = pParty_Id)
       AND (pBranch_Id = 0 OR m.Branch_Id = pBranch_Id)
       AND (
            pGst_Filter = 0
            OR (pGst_Filter = 1 AND IFNULL(TRIM(pt.GstIn), '') <> '')
            OR (pGst_Filter = 2 AND IFNULL(TRIM(pt.GstIn), '') = '')
       )
     ORDER BY m.Invoice_Date, m.Trading_Id, tp.Sl;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_ITEMWISE_PURCHASE;
DELIMITER $$
CREATE PROCEDURE USP_RPT_ITEMWISE_PURCHASE(IN pFrm DATE,
    IN pTo DATE,
    IN pParty_Id INT,
    IN pBranch_Id INT,
    IN pCat_Id INT,
    IN pSubCat_Id INT)
BEGIN

    SELECT
        i.Prod_Code,
        i.Prod_ShortNm,
        IFNULL(c.Prd_CateNm, '') AS Cate_Name,
        IFNULL(UDF_GET_UNIT_NAME(p.Unit_Id), '') AS Unit_Name,
        SUM(IFNULL(p.Item_Qty, 0)) AS Qty,
        CASE
            WHEN SUM(IFNULL(p.Item_Qty, 0)) = 0 THEN 0
            ELSE ROUND(SUM(IFNULL(p.Item_Total, 0)) / SUM(p.Item_Qty), 2)
        END AS Item_Rate,
        SUM(IFNULL(p.Taxable_Amt, 0)) AS Taxable_Amt,
        SUM(IFNULL(p.SGST_Amt, 0) + IFNULL(p.CGST_Amt, 0)) AS GST_Amt,
        SUM(IFNULL(p.Net_Amt, 0)) AS Net_Amt
    FROM trans_trading m
    INNER JOIN trans_trading_products p ON p.Trading_Id = m.Trading_Id
    INNER JOIN mst_product i ON i.Prod_Id = p.Prod_Id
    LEFT JOIN mst_prod_category c ON c.Prd_CateId = i.Cate_Id
    WHERE m.Tranding_Type = 2
      AND IFNULL(m.Status_Cd, 1) = 1
      AND m.Invoice_Date BETWEEN pFrm AND pTo
      AND (pParty_Id = 0 OR m.Party_Id = pParty_Id)
      AND (pBranch_Id = 0 OR m.Branch_Id = pBranch_Id)
      AND (pCat_Id = 0 OR i.Cate_Id = pCat_Id)
      AND (pSubCat_Id = 0 OR i.SubCate_Id = pSubCat_Id)
    GROUP BY i.Prod_Id, i.Prod_Code, i.Prod_ShortNm, c.Prd_CateNm, p.Unit_Id
    ORDER BY i.Prod_ShortNm, i.Prod_Code;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_SALES_REGISTER;
DELIMITER $$
CREATE PROCEDURE USP_RPT_SALES_REGISTER(IN pFrm DATE,
    IN pTo DATE,
    IN pBranch_Id INT,
    IN pMode TINYINT,
    IN pCat_Id INT)
BEGIN

    SELECT
        m.Trading_Id,
        m.Invoice_No,
        m.Invoice_Date,
        CASE IFNULL(m.Pay_Mode, 1)
            WHEN 1 THEN 'Cash'
            WHEN 2 THEN 'Bank'
            WHEN 3 THEN 'Credit'
            ELSE ''
        END AS Pay_Mode,
        CASE WHEN m.Agent_Id IS NULL THEN 'Counter' ELSE 'Agent' END AS Sale_Type,
        IFNULL(p.Party_Name, '') AS Party_Name,
        IFNULL(a.Agent_Name, '') AS Agent_Name,
        IFNULL(i.Prod_ShortNm, '') AS Item_Name,
        IFNULL(tp.Gst_Code, '') AS HSN_No,
        IFNULL(tp.Item_Qty, 0) AS Item_Qty,
        IFNULL(UDF_GET_UNIT_NAME(tp.Unit_Id), '') AS Unit_Name,
        IFNULL(tp.Item_Rate, 0) AS Item_Rate,
        IFNULL(tp.Item_Total, 0) AS Item_Total,
        IFNULL(tp.Taxable_Amt, 0) AS Taxable_Amt,
        (IFNULL(tp.SGST_Prcnt, 0) + IFNULL(tp.CGST_Prcnt, 0)) AS GST_Prcnt,
        (IFNULL(tp.SGST_Amt, 0) + IFNULL(tp.CGST_Amt, 0)) AS GST_Amt,
        IFNULL(m.Round_Off, 0) AS Round_Off,
        IFNULL(tp.Net_Amt, 0) AS Net_Amt
     FROM trans_trading m
     INNER JOIN trans_trading_products tp ON tp.Trading_Id = m.Trading_Id
     INNER JOIN mst_product i ON i.Prod_Id = tp.Prod_Id
     LEFT JOIN mst_party p ON p.Party_Id = m.Party_Id
     LEFT JOIN mst_agent a ON a.Agent_Id = m.Agent_Id
     WHERE m.Tranding_Type = 3
       AND IFNULL(m.Status_Cd, 1) = 1
       AND m.Invoice_Date BETWEEN pFrm AND pTo
       AND (pBranch_Id = 0 OR m.Branch_Id = pBranch_Id)
       AND (
            pMode = 0
            OR (pMode = 1 AND m.Agent_Id IS NULL)
            OR (pMode = 2 AND m.Agent_Id IS NOT NULL)
       )
       AND (pCat_Id = 0 OR i.Cate_Id = pCat_Id)
     ORDER BY m.Invoice_Date, m.Trading_Id, tp.Sl;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_AGENT_COMMISSION_SEARCH;
DELIMITER $$
CREATE PROCEDURE USP_RPT_AGENT_COMMISSION_SEARCH(IN pComm_Month TINYINT,
    IN pComm_Year SMALLINT,
    IN pBranch_Id INT,
    IN pSettle_Frm DATE,
    IN pSettle_To DATE,
    IN pAgent_Id INT)
BEGIN

    SELECT
        a.Agent_Id,
        a.Agent_Code,
        a.Agent_Name,
        ROUND(SUM(IFNULL(tp.Taxable_Amt, 0)), 2) AS Total_Sale,
        ROUND(SUM(
            IFNULL(tp.Taxable_Amt, 0)
            * IFNULL(NULLIF(p.Sales_Comm, 0), IFNULL(c.Agent_Comm, 0))
            / 100
        ), 2) AS Total_Comm,
        CASE WHEN g.Comm_Id IS NULL THEN 0 ELSE 1 END AS Is_Generated,
        IFNULL(g.Comm_Id, 0) AS Comm_Id,
        g.Created_On AS Generated_On
     FROM trans_trading t
     INNER JOIN mst_agent a ON a.Agent_Id = t.Agent_Id
     INNER JOIN trans_trading_products tp ON tp.Trading_Id = t.Trading_Id
     INNER JOIN mst_product p ON p.Prod_Id = tp.Prod_Id
     LEFT JOIN mst_prod_category c ON c.Prd_CateId = p.Cate_Id
     LEFT JOIN trn_agent_commission g
        ON g.Agent_Id = a.Agent_Id
       AND g.Comm_Month = pComm_Month
       AND g.Comm_Year = pComm_Year
       AND IFNULL(g.Branch_Id, 0) = pBranch_Id
     WHERE t.Tranding_Type = 3
       AND IFNULL(t.Agent_Id, 0) > 0
       AND IFNULL(t.Status_Cd, 0) = 1
       AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
       AND t.Settle_Date BETWEEN pSettle_Frm AND pSettle_To
       AND (pBranch_Id = 0 OR t.Branch_Id = pBranch_Id)
       AND (pAgent_Id = 0 OR t.Agent_Id = pAgent_Id)
     GROUP BY a.Agent_Id, a.Agent_Code, a.Agent_Name, g.Comm_Id, g.Created_On
     ORDER BY a.Agent_Name;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_MASTER;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_MASTER(IN pAgent_Id INT)
BEGIN

    SELECT Agent_Id, Agent_Code, Agent_Name
      FROM mst_agent
     WHERE Agent_Id = pAgent_Id
     LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_COMMISSION_HEADER;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_COMMISSION_HEADER(IN pAgent_Id INT,
    IN pComm_Month TINYINT,
    IN pComm_Year SMALLINT,
    IN pBranch_Id INT)
BEGIN

    SELECT Comm_Id, Total_Sale, Total_Comm, Created_On
      FROM trn_agent_commission
     WHERE Agent_Id = pAgent_Id
       AND Comm_Month = pComm_Month
       AND Comm_Year = pComm_Year
       AND IFNULL(Branch_Id, 0) = pBranch_Id
     LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_COMMISSION_DTL;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_COMMISSION_DTL(IN pComm_Id BIGINT)
BEGIN

    SELECT
        IFNULL(Cate_Id, 0) AS Cate_Id,
        IFNULL(Cate_Name, 'Uncategorised') AS Cate_Name,
        Sale_Amt AS Total_Sale,
        Comm_Percent,
        Comm_Amt AS Total_Comm
     FROM trn_agent_commission_dtl
     WHERE Comm_Id = pComm_Id
     ORDER BY Cate_Name;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_RPT_AGENT_COMMISSION_BY_CATEGORY;
DELIMITER $$
CREATE PROCEDURE USP_RPT_AGENT_COMMISSION_BY_CATEGORY(IN pAgent_Id INT,
    IN pSettle_Frm DATE,
    IN pSettle_To DATE,
    IN pBranch_Id INT)
BEGIN

    SELECT
        IFNULL(c.Prd_CateId, 0) AS Cate_Id,
        IFNULL(c.Prd_CateNm, 'Uncategorised') AS Cate_Name,
        ROUND(SUM(IFNULL(tp.Taxable_Amt, 0)), 2) AS Total_Sale,
        ROUND(
            CASE
                WHEN SUM(IFNULL(tp.Taxable_Amt, 0)) = 0 THEN 0
                ELSE SUM(
                    IFNULL(tp.Taxable_Amt, 0)
                    * IFNULL(NULLIF(p.Sales_Comm, 0), IFNULL(c.Agent_Comm, 0))
                    / 100
                ) * 100 / SUM(IFNULL(tp.Taxable_Amt, 0))
            END
        , 2) AS Comm_Percent,
        ROUND(SUM(
            IFNULL(tp.Taxable_Amt, 0)
            * IFNULL(NULLIF(p.Sales_Comm, 0), IFNULL(c.Agent_Comm, 0))
            / 100
        ), 2) AS Total_Comm
     FROM trans_trading t
     INNER JOIN trans_trading_products tp ON tp.Trading_Id = t.Trading_Id
     INNER JOIN mst_product p ON p.Prod_Id = tp.Prod_Id
     LEFT JOIN mst_prod_category c ON c.Prd_CateId = p.Cate_Id
     WHERE t.Tranding_Type = 3
       AND t.Agent_Id = pAgent_Id
       AND IFNULL(t.Status_Cd, 0) = 1
       AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
       AND t.Settle_Date BETWEEN pSettle_Frm AND pSettle_To
       AND (pBranch_Id = 0 OR t.Branch_Id = pBranch_Id)
     GROUP BY c.Prd_CateId, c.Prd_CateNm
     ORDER BY Cate_Name;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_COMMISSION_SETTLED_AGENTS;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_COMMISSION_SETTLED_AGENTS(IN pSettle_Frm DATE,
    IN pSettle_To DATE,
    IN pBranch_Id INT,
    IN pAgent_Id INT)
BEGIN

    SELECT DISTINCT t.Agent_Id
      FROM trans_trading t
     WHERE t.Tranding_Type = 3
       AND IFNULL(t.Agent_Id, 0) > 0
       AND IFNULL(t.Status_Cd, 0) = 1
       AND CAST(IFNULL(t.Is_Settle, 0) AS UNSIGNED) = 1
       AND t.Settle_Date BETWEEN pSettle_Frm AND pSettle_To
       AND (pBranch_Id = 0 OR t.Branch_Id = pBranch_Id)
       AND (pAgent_Id = 0 OR t.Agent_Id = pAgent_Id)
     ORDER BY t.Agent_Id;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_COMMISSION_EXISTS;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_COMMISSION_EXISTS(IN pAgent_Id INT,
