     LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_SALE_REPORT_SUMMARY;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_SALE_REPORT_SUMMARY(IN pAgent_Id INT,
    IN pFrm DATE,
    IN pTo DATE)
BEGIN

    SELECT
        IFNULL(SUM(CASE WHEN IFNULL(Pay_Mode, 0) = 1 THEN Net_Amt ELSE 0 END), 0) AS Cash_Amt,
        IFNULL(SUM(CASE WHEN IFNULL(Pay_Mode, 0) = 2 THEN Net_Amt ELSE 0 END), 0) AS Bank_Amt,
        IFNULL(SUM(CASE WHEN IFNULL(Pay_Mode, 0) = 3 THEN Net_Amt ELSE 0 END), 0) AS Credit_Amt,
        IFNULL(SUM(Net_Amt), 0) AS Net_Amt,
        IFNULL(SUM(IFNULL(Round_Off, 0)), 0) AS Round_Off_Amt,
        (
            SELECT IFNULL(SUM(t.Amount), 0)
              FROM trn_party_trans t
              INNER JOIN mst_party p
                      ON p.Party_Id = t.Party_Id
                     AND p.Party_Type = 2
                     AND p.Cust_Agent_Id = pAgent_Id
             WHERE t.Created_By = pAgent_Id
               AND t.Trans_Type = 'C'
               AND IFNULL(t.Trading_Id, 0) = 0
               AND t.Trans_Mode IN (1, 2)
               AND t.Trans_Date BETWEEN pFrm AND pTo
        ) AS Collected_Amt,
        (
            SELECT IFNULL(SUM(GREATEST(UDF_CAL_PARTY_CLOSING(p.Party_Id, pTo), 0)), 0)
              FROM mst_party p
             WHERE p.Party_Type = 2
               AND p.Cust_Agent_Id = pAgent_Id
               AND EXISTS (
                    SELECT 1
                      FROM trans_trading t
                     WHERE t.Party_Id = p.Party_Id
                       AND t.Agent_Id = pAgent_Id
                       AND t.Tranding_Type = 3
                       AND IFNULL(t.Pay_Mode, 0) = 3
                       AND t.Invoice_Date BETWEEN pFrm AND pTo
                )
        ) AS Unsettled_Amt
     FROM trans_trading
    WHERE Agent_Id = pAgent_Id
      AND Tranding_Type = 3
      AND Invoice_Date BETWEEN pFrm AND pTo;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_SEARCH_AGENT_CUSTOMER_DUE;
DELIMITER $$
CREATE PROCEDURE USP_SEARCH_AGENT_CUSTOMER_DUE(IN pAsOn DATE,
    IN pAgent_Id INT,
    IN pParty_Id INT,
    IN pSearch VARCHAR(100))
BEGIN

    SELECT
        p.Party_Id,
        p.Party_Code,
        p.Party_Name,
        IFNULL(p.Contact_No, '') AS Contact_No,
        IFNULL(p.Credit_Limit, 0) AS Credit_Limit,
        IFNULL(p.Opening_Bal, 0) AS Opening_Bal,
        IFNULL((
            SELECT SUM(t.Amount)
              FROM trn_party_trans t
             WHERE t.Party_Id = p.Party_Id
               AND t.Trans_Type = 'D'
               AND t.Trans_Date <= pAsOn
               AND (IFNULL(t.Trading_Id, 0) = 0 OR t.Trans_Mode = 3)
        ), 0) AS Debit_Amt,
        IFNULL((
            SELECT SUM(t.Amount)
              FROM trn_party_trans t
             WHERE t.Party_Id = p.Party_Id
               AND t.Trans_Type = 'C'
               AND t.Trans_Date <= pAsOn
               AND (IFNULL(t.Trading_Id, 0) = 0 OR t.Trans_Mode = 3)
        ), 0) AS Paid_Amt,
        UDF_CAL_PARTY_CLOSING(p.Party_Id, pAsOn) AS Remaining_Amt,
        (
            SELECT MIN(tr.Invoice_Date)
              FROM trans_trading tr
             WHERE tr.Party_Id = p.Party_Id
               AND tr.Agent_Id = pAgent_Id
               AND tr.Tranding_Type = 3
               AND IFNULL(tr.Pay_Mode, 0) = 3
               AND IFNULL(tr.Status_Cd, 1) = 1
        ) AS Due_Date
     FROM mst_party p
    WHERE p.Party_Type = 2
      AND p.Cust_Agent_Id = pAgent_Id
      AND IFNULL(p.Status_Cd, 1) = 1
      AND (pParty_Id = 0 OR p.Party_Id = pParty_Id)
      AND (
            pSearch = ''
            OR p.Party_Code LIKE CONCAT('%', pSearch, '%')
            OR p.Party_Name LIKE CONCAT('%', pSearch, '%')
            OR IFNULL(p.Contact_No, '') LIKE CONCAT('%', pSearch, '%')
      )
    ORDER BY Remaining_Amt DESC, p.Party_Name ASC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_CUSTOMER_PARTY;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_CUSTOMER_PARTY(IN pParty_Id INT,
    IN pAgent_Id INT)
BEGIN

    SELECT Party_Id, Party_Code, Party_Name
      FROM mst_party
     WHERE Party_Id = pParty_Id
       AND Party_Type = 2
       AND Cust_Agent_Id = pAgent_Id
     LIMIT 1;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_AGENT_CUSTOMER_PAYMENT_HISTORY;
DELIMITER $$
CREATE PROCEDURE USP_GET_AGENT_CUSTOMER_PAYMENT_HISTORY(IN pParty_Id INT)
BEGIN

    SELECT
        t.Id,
        t.Trans_Date,
        t.Trans_Type,
        t.Amount,
        t.Trans_Mode,
        t.Remarks,
        t.Trading_Id,
        t.Txn_Id,
        CASE
            WHEN t.Trans_Type = 'D' THEN 'Credit Sale'
            WHEN t.Trans_Type = 'C' THEN 'Payment'
            ELSE t.Trans_Type
        END AS Entry_Type,
        CASE
            WHEN t.Trans_Type = 'C' AND t.Trans_Mode = 1 THEN 'Cash'
            WHEN t.Trans_Type = 'C' AND t.Trans_Mode = 2 THEN 'Bank / UPI'
            WHEN t.Trans_Type = 'D' AND t.Trans_Mode = 3 THEN 'Credit'
            ELSE '-'
        END AS Mode_Name,
        CASE
            WHEN t.Trading_Id IS NOT NULL THEN (
                SELECT tr.Invoice_No FROM trans_trading tr WHERE tr.Trading_Id = t.Trading_Id LIMIT 1
            )
            WHEN LOCATE('|', IFNULL(t.Remarks, '')) > 0 THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', 1))
            WHEN t.Txn_Id IS NOT NULL THEN (
                SELECT m.Vou_No FROM trans_voucher_master m WHERE m.Voucher_Id = t.Txn_Id LIMIT 1
            )
            ELSE ''
        END AS Ref_No,
        CASE
            WHEN (LENGTH(IFNULL(t.Remarks, '')) - LENGTH(REPLACE(IFNULL(t.Remarks, ''), '|', ''))) >= 2
                THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', -1))
            WHEN LOCATE('|', IFNULL(t.Remarks, '')) > 0
                THEN TRIM(SUBSTRING_INDEX(t.Remarks, '|', -1))
            ELSE IFNULL(t.Remarks, '')
        END AS Particulars
     FROM trn_party_trans t
    WHERE t.Party_Id = pParty_Id
      AND (IFNULL(t.Trading_Id, 0) = 0 OR t.Trans_Mode = 3)
    ORDER BY t.Trans_Date DESC, t.Id DESC;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_GLHEAD_ACTIVE_PAIR;
DELIMITER $$
CREATE PROCEDURE USP_GET_GLHEAD_ACTIVE_PAIR(IN pDebit_Id INT,
    IN pCredit_Id INT)
BEGIN

    SELECT Account_Id, Is_Active
      FROM mst_acct_glhead
     WHERE Account_Id IN (pDebit_Id, pCredit_Id);

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_GET_VOUCHER_MASTER_PAIR;
DELIMITER $$
CREATE PROCEDURE USP_GET_VOUCHER_MASTER_PAIR(IN pVoucher_Id INT)
BEGIN

    SELECT Voucher_Id, Vou_No
      FROM trans_voucher_master
     WHERE Voucher_Id = pVoucher_Id
       AND Trans_Type = 9
       AND IFNULL(Type_Id, 0) = 0;

END$$
DELIMITER ;


DROP PROCEDURE IF EXISTS USP_ENSURE_NUMBER_SERIES;
DELIMITER $$
CREATE PROCEDURE USP_ENSURE_NUMBER_SERIES(IN pElement_Name VARCHAR(10),
    IN pYear_Id INT,
    IN pBranch_Id INT)
BEGIN

    INSERT INTO stores_id (Element_Name, Element_For, Cur_Val, Year_Id, Branch_Id)
    SELECT pElement_Name,
           CASE WHEN pElement_Name = 'CON' THEN 'For Contra Voucher Generate'
                ELSE 'For Journal Voucher Generate' END,
           0,
           pYear_Id,
           pBranch_Id
      FROM DUAL
     WHERE NOT EXISTS (
        SELECT 1 FROM stores_id
         WHERE Element_Name = pElement_Name
           AND Year_Id = pYear_Id
           AND (Branch_Id IS NULL OR Branch_Id = pBranch_Id)
     );

END$$
DELIMITER ;
